[[nodiscard]] inline std::string_view board_id_name(const BoardId value) {
  const auto index = static_cast<std::size_t>(value);
  return index < kBoardIdNames.size() ? kBoardIdNames[index] : std::string_view{};
}

[[nodiscard]] inline bool board_id_from_name(const std::string_view name,
                                                  BoardId& value) {
  for (std::size_t index = 0; index < kBoardIdNames.size(); ++index) {
    if (kBoardIdNames[index] == name) {
      value = static_cast<BoardId>(index);
      return true;
    }
  }
  return false;
}

